package com.makemytrip.makemytrip.models;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;
@Document("flight_status") public class FlightStatus {
 public enum State { ON_TIME, BOARDING, DELAYED, DEPARTED, IN_AIR, LANDED, CANCELLED }
 @Id private String id;@Indexed(unique=true) private String flightId;@Indexed private String flightNumber;private String airline;private String origin;private String destination;private String scheduledDeparture;private String estimatedDeparture;private String scheduledArrival;private String estimatedArrival;private String terminal;private String gate;private State status=State.ON_TIME;private int delayMinutes;private String delayReason;private Instant lastUpdated=Instant.now();private boolean simulated;
 public String getId(){return id;} public String getFlightId(){return flightId;}public void setFlightId(String v){flightId=v;}public String getFlightNumber(){return flightNumber;}public void setFlightNumber(String v){flightNumber=v;}public String getAirline(){return airline;}public void setAirline(String v){airline=v;}public String getOrigin(){return origin;}public void setOrigin(String v){origin=v;}public String getDestination(){return destination;}public void setDestination(String v){destination=v;}public String getScheduledDeparture(){return scheduledDeparture;}public void setScheduledDeparture(String v){scheduledDeparture=v;}public String getEstimatedDeparture(){return estimatedDeparture;}public void setEstimatedDeparture(String v){estimatedDeparture=v;}public String getScheduledArrival(){return scheduledArrival;}public void setScheduledArrival(String v){scheduledArrival=v;}public String getEstimatedArrival(){return estimatedArrival;}public void setEstimatedArrival(String v){estimatedArrival=v;}public String getTerminal(){return terminal;}public void setTerminal(String v){terminal=v;}public String getGate(){return gate;}public void setGate(String v){gate=v;}public State getStatus(){return status;}public void setStatus(State v){status=v;}public int getDelayMinutes(){return delayMinutes;}public void setDelayMinutes(int v){delayMinutes=v;}public String getDelayReason(){return delayReason;}public void setDelayReason(String v){delayReason=v;}public Instant getLastUpdated(){return lastUpdated;}public void setLastUpdated(Instant v){lastUpdated=v;}public boolean isSimulated(){return simulated;}public void setSimulated(boolean v){simulated=v;}
}
